window.QUESTIONS.push(...[{"id":"112-1-A-26","exam":"112-1","q":26,"unit":"影像與多媒體","topic":"數位科技","stem":"有關數位影像的敘述，下列何者正確？","options":["點陣圖放大時，圖像不會失真","點陣圖是以數學方程式表現圖像","向量圖放大後，圖像邊緣不會出現鋸齒狀","向量圖中的像素總數愈多，可表現的色彩數愈多"],"answer":"C","official":"(A) 點陣圖放大時，圖像會失真\n(B) 點陣圖是以像素表現圖像\n(D) 點陣圖中的像素位元愈大，可表現的色彩數愈多"},{"id":"112-1-A-27","exam":"112-1","q":27,"unit":"電腦與數位資料","topic":"數位科技","stem":"小嵐採用蘋果公司的 HomeKit 建置智慧家庭，透過手機設定，當回家後冷氣與電燈會自動同時開啟，\n下列何者最不可能是 HomeKit 的資料處理方式？","options":["即時處理","批次處理","連線處理","離線處理"],"answer":"D","official":"透過手機設定家裡的智慧家庭，屬於連線處理；回到\n家推開門，立即觸發家電，屬於即時處理；觸發家電\n會同時開啟冷氣與電燈，屬於批次處理"},{"id":"112-1-A-28","exam":"112-1","q":28,"unit":"網頁與程式設計","topic":"數位科技","stem":"ChatGPT 稱為聊天生成型預訓練變換模型，透過 ChatGPT 可以快速產生圖文並茂的繪本或影片，甚至\n可以依據需求產生程式碼，請問 ChatGPT 屬於哪個世代的電腦技術？","options":["第五代","第四代","第三代","第二代"],"answer":"A","official":"ChatGPT 是使用大量資料以機器學習方式訓練出的人\n工智慧程式，還可以進行如：自動生成文字、自動問\n答、自動摘要等多種任務，所以屬於第五代電腦技術"},{"id":"112-1-A-29","exam":"112-1","q":29,"unit":"電腦與數位資料","topic":"數位科技","stem":"有關暫存器的敘述，下列何者正確？","options":["指令暫存器的用途是存放 CPU 下一個要執行的指令","指令暫存器的用途是存放 CPU 正在執行的指令在主記憶體中的位址","程式計數器的用途是存放 CPU 下一個要執行的指令在主記憶體中的位址","程式計數器的用途是存放 CPU 下一個要執行的指令"],"answer":"C","official":"(A)(B) 指令暫存器的用途是存放CPU正在執行的指令\n(C)(D) 程式計數器的用途是存放 CPU 下一個要執行\n的指令在主記憶中的位址"},{"id":"112-1-A-30","exam":"112-1","q":30,"unit":"電腦與數位資料","topic":"數位科技","stem":"下列記憶體何者執行速度最快？","options":["256 GB 記憶卡","2 TB 固態硬碟","64 位元暫存器","32 MB L1 快取記憶體"],"answer":"C","official":"記憶體執行的速度由快到慢：暫存器→快取記憶體→\n固態硬碟→記憶卡"},{"id":"112-1-A-31","exam":"112-1","q":31,"unit":"文書與簡報","topic":"數位科技","stem":"有關 CPU 效能的敘述，下列何者錯誤？","options":["CPU Word(字組)愈大，效能愈好","CPU 資料匯流排寬度愈大，效能愈好","CPU 時脈頻率愈高，效能愈好","CPU 時脈週期愈長，效能愈好"],"answer":"D","official":"(D) CPU 的時脈週期愈長，效能愈差"},{"id":"112-1-A-32","exam":"112-1","q":32,"unit":"電腦與數位資料","topic":"數位科技","stem":"有關記憶單元的敘述，下列何者正確？","options":["DRAM 存取速度比 SRAM 慢且單位成本低","SRAM 單位成本高，因為執行速度較 DRAM 快，且需要週期性充放電","ROM 只能讀取不能寫入，而 DRAM 可讀取並寫入，故電腦開機使用的 BIOS 採用 DRAM 儲存","固態硬碟有快速執行的特性，故採用 SRAM 記憶體"],"answer":"A","official":"(B) SRAM 不需要週期性充放電\n(C) 電腦開機程式(BIOS)採用 Flash ROM 儲存\n(D) 固態硬碟採用 Flash ROM 記憶體"},{"id":"112-1-A-33","exam":"112-1","q":33,"unit":"影像與多媒體","topic":"數位科技","stem":"有關電腦軟體的敘述，下列何者正確？","options":["SketchUp 是動畫軟體，可以用來製作 2D 動畫","Safari 是瀏覽器軟體，可以用來連接全球資訊網","Microsoft Teams 可以用來登入遠端主機","GIMP 是電腦輔助設計軟體，可以用於室內設計"],"answer":"B","official":"(A) SketchUp 是電腦輔助設計軟體，適用於繪製建築\n或室內設計的 3D 圖\n(C) Microsoft Teams 是視訊會議軟體\n(D) GIMP 是開放原始碼的影像處理軟體"},{"id":"112-1-A-34","exam":"112-1","q":34,"unit":"網頁與程式設計","topic":"數位科技","stem":"志玲將撰寫好的 PHP 程式碼上傳到 Heroku，透過雲端運算，不需架設伺服器，即可看到 PHP 程式碼運\n行結果，以上過程最可能是哪一種模式的雲端服務？","options":["IaaS","PaaS","SaaS","CaaS"],"answer":"B","official":"將 PHP 程式碼上傳到 Heroku 雲端平台，不需架設伺\n服器即可運行 PHP 程式碼，Heroku 屬於平台，即雲\n端服務 PaaS"},{"id":"112-1-A-35","exam":"112-1","q":35,"unit":"文書與簡報","topic":"數位科技","stem":"依林利用軟體完成專題製作課程的作業，下列敘述何者正確？","options":["利用 Impress 製作簡報","透過 Numbers 編輯專題報告的小論文","將問卷資料輸入 Base 製作統計圖表","透過 FileZilla 與組員進行視訊會議，並且傳送檔案"],"answer":"A","official":"(B) Numbers 屬於電子試算表軟體\n(C) Base 屬於資料庫軟體\n(D) FileZilla 屬於檔案傳輸軟體","scan":"data:image/webp;base64,"},{"id":"112-1-A-36","exam":"112-1","q":36,"unit":"電腦與數位資料","topic":"數位科技","stem":"有關設備與媒體的敘述，下列何者正確？","options":["條碼是用來存放資料的介質，屬於輸入設備","電競耳機於遊戲過程可以語音通話，屬於輸出設備","HomePod 智慧音箱透過 Siri 語音控制，即時播放音樂，屬於輸出設備","智慧門鎖通常可以採用指紋解鎖開門，屬於輸入設備"],"answer":"D","official":"(A) 條碼是用來存放資料的介質，屬於輸入媒體\n(B) 電競耳機可以聽到聲音且進行語音通話，屬於輸\n出入設備\n(C) HomePod 智慧音箱透過 Siri 語音控制，可以播放\n音樂，屬於輸出入設備"},{"id":"112-1-A-37","exam":"112-1","q":37,"unit":"電腦與數位資料","topic":"數位科技","stem":"有關電腦 I/O 連接埠的敘述，下列何者正確？","options":["筆記型電腦可以透過連接電視的 HDMI 連接埠投放影音","多功能事務機可以透過 RJ-45、USB、SATA 連接埠連接電腦","顯示卡可以透過 HDMI 連接埠連接主機板","外接硬碟可以透過 USB、Thunderbolt、DVI 連接埠連接電腦"],"answer":"A","official":"(B) 多功能事務機可以透過 RJ-45、USB 連接埠連接\n電腦\n(C) 顯示卡可以透過擴充槽連接主機板\n(D) 外接硬碟可以透過 USB、Thunderbolt 連接埠連接\n電腦，DVI 屬於螢幕連接埠"},{"id":"112-1-A-38","exam":"112-1","q":38,"unit":"雲端與新興科技","topic":"數位科技","stem":"有關巨量資料與區塊鏈的敘述，下列何者正確？","options":["巨量資料有資料量大、資料少樣性、資料量增加速度快之特性","區塊鏈具有資料集中儲放、可驗證之特性","乙太幣採用區塊鏈技術，可有效減低數位貨幣被篡改的風險","NFT 加密藝術品交易，每筆交易都可以決定是否公開在區塊鏈上"],"answer":"C","official":"(A) 巨量資料有資料量大、資料多樣性、資料量增加\n速度快之特性\n(B) 區塊鏈具有去中心化、可驗證、不可變、公開透\n明之特性\n(D) NFT 加密藝術品交易，採用區塊鏈技術，故所有\n交易都必需是公開在區塊鏈上"},{"id":"112-1-A-39","exam":"112-1","q":39,"unit":"網頁與程式設計","topic":"數位科技","stem":"GitHub 是一個線上軟體原始碼代管服務平台，程式開發人員可以將程式碼上傳，並且公開程式碼讓所\n有人共同監督與維護，下列哪個軟體的原始碼最有可能出現在 GitHub 平台？","options":["Line","Chrome","Acrobat","Firefox"],"answer":"D","official":"GitHub 是一個線上軟體原始碼代管服務平台，在此\n平台公開原始碼讓所有人共同監督與維護，這是屬於\nGPL 授權開放原始碼的管理方式，所以最可能是自由\n軟體 Firefox"},{"id":"112-1-A-40","exam":"112-1","q":40,"unit":"作業系統與軟體","topic":"數位科技","stem":"米希亞針對作業系統製作專題報導，下列何者正確？","options":["蘋果公司的平板電腦採用 MacOS，透過並行(Sidecar)可以延伸螢幕","Linux 屬於單人多工的作業系統，同一時間允許一個使用者執行多個程式","MS-DOS 允許同一時間執行多個程式","Android 可以在網路上找到原始碼，依需求進行新增、修改"],"answer":"D","official":"(A) 蘋果公司的平板電腦採用 iPad OS，並行(Sidecar)\n是 Mac OS 運行的程式，用來把 iPad 當做 Mac 的第\n二部顯示器\n(B) Linux 屬於多人多工的作業系統，同一時間允許多\n個使用者執行多個程式\n(C) MS-DOS 只允許單一使用者同一時間執行 1 個程\n式，屬於單人單工的作業系統"},{"id":"112-1-A-41","exam":"112-1","q":41,"unit":"作業系統與軟體","topic":"數位科技","stem":"下列何者是作業系統必備的功能？","options":["圖形化操作介面","記憶體管理","影音播放程式","系統備份工具"],"answer":"B","official":"作業系統的功能包含程序管理、記憶體管理、週邊設\n備管理、檔案管理、提供使用者介面，而使用者介面\n有純文字及圖形化 GUI 兩種，部分作業系統(如\nMS-DOS)只具有純文字介面，故圖形化使用者介面並\n非作業系統的必備功能"},{"id":"112-1-A-42","exam":"112-1","q":42,"unit":"網頁與程式設計","topic":"數位科技","stem":"有關程式語言的敘述，下列何者正確？","options":["低階語言是由 0 與 1 來表示要執行的命令","高階語言撰寫的程式可於不同硬體的電腦執行，故可攜性低","編譯器將原始碼翻譯成目的碼，第二次執行時不需將原始碼再次翻譯，藉以提升執行速度","直譯器會將指令逐行翻譯執行，當程式發生錯誤時較不易除錯"],"answer":"C","official":"(A) 低階語言包含機器語言及組合語言，機器語言是\n由 0 與 1 來表示要執行的命令，而組合語言則是以助\n憶碼來表示要執行的指令\n(B) 高階語言撰寫的程式可於不同硬體規格的電腦執\n行，故可攜性高\n(D) 直譯器會將指令逐行翻譯執行，當程式發生錯誤\n時較容易除錯"},{"id":"112-1-A-43","exam":"112-1","q":43,"unit":"電腦與數位資料","topic":"數位科技","stem":"有關匯流排介面的敘述，下列何者正確？","options":["PCI-Express 使用串列、獨立通道、全雙工傳輸","並列傳輸適合長距離傳輸，一次可以傳送多個位元","顯示卡插入主機板上的介面卡擴充槽後，不需任何設定就可以立即使用","SATA 採用並列傳輸，具熱插拔特性，可隨時安裝或移除設備"],"answer":"A","official":"(B) 串(序)列傳輸適合長距離傳輸，一次只傳送 1 個\n位元\n(C) 顯示卡插入主機板上的介面卡擴充槽後，若作業\n系統未能支援，就需安裝驅動程式才能使用\n(D) SATA 採用串列傳輸"},{"id":"112-1-A-44","exam":"112-1","q":44,"unit":"雲端與新興科技","topic":"數位科技","stem":"蘋果公司 Vision Pro 頭盔讓數位內容存在於使用者的空間之中，透過使用者的眼睛、雙手與聲音即可控\n制，旁人靠近你時，頭盔鏡面可以顯示出你的雙眼，讓旁人知道你確實透過頭盔正看著他們，請問以上\n敘述最不可能用到下列哪項技術？","options":["虛擬實境","區塊鏈","機器學習","擴增實境"],"answer":"B","official":"蘋果公司 Vision Pro 頭盔可以讓數位內容存在於使用\n者的空間之中，即虛擬實境(VR)、擴增實境(AR)及混\n合實境間的切換，當有人靠近你時，感測器會即時感\n知，讓頭盔鏡面可以顯示出你的雙眼，藉由多次偵測\n他人與自己的距離，來進行機器學習，提升動作的正\n確性，所以裡面不會運用到區塊鏈的技術"},{"id":"112-1-A-45","exam":"112-1","q":45,"unit":"電腦與數位資料","topic":"數位科技","stem":"財金新聞報導台積電 2 奈米(nanometre)製程 2025 年將進入量產，技術將領先全世界，請問 1 公分是報\n導中提及的 2 奈米的幾倍？","options":["9 0.5 10 ×","8 0.5 10 ×","7 5 10 ×","6 5 10 ×"],"answer":"D","official":"6\n99\n11 5 10\n2 2 2 2 100 −− ＝ ＝× × ××\n公分 公分\n公尺 公分"},{"id":"112-1-A-46","exam":"112-1","q":46,"unit":"影像與多媒體","topic":"數位科技","stem":"高解析音樂取樣頻率 192 KHz，取樣大小 16 bits，則下列何者正確？","options":["聲音的頻率範圍為 0-192 KHz","取樣大小 16 bits 表示需用 65536 個位階來解析取樣","採用雙聲道來錄製 10 秒的音訊，檔案大小需要 3.75 MB","取樣頻率愈大，取樣後的聲音檔案愈小"],"answer":"B","official":"(A) 取樣頻率 192 KHz 表示每秒取樣 3 192 10 × 次\n(B) 取樣大小 16 bits 表示需用 65536 個位階來解析取\n樣， 16 2 65536 ＝\n(C) 採用雙聲道來錄製 10 秒的音訊，檔案大小需要取\n樣頻率 192 K × 取樣大小 16 bits × 2 聲道 × 10 秒\n＝ 7.5 MB\n(D) 取樣頻率愈大，取樣後的聲音檔案愈大"},{"id":"112-1-A-47","exam":"112-1","q":47,"unit":"資安與資訊倫理","topic":"數位科技","stem":"某 CPU 執行速度 500 MIPS(每秒執行百萬指令)，執行 1 個指令需要 4 個週期，請問該 CPU 的時脈頻率為多少？","options":["125 MHz", "2 GHz", "2.5 GHz", "5 GHz"],"answer":"B","official":"CPU 執行速度 500 MIPS 即 1 秒執行 500 M 個指令，\n執行 1 個指令需 1\n500 M\n秒，題意所示執行 1 個指令需\n要 4 個週期，故 1 4\n500 M ＝ 週期，週期 14 500 M ＝ × ，\n頻率與週期互為倒數，所以 CPU 的時脈為 2 GHz","scan":"data:image/webp;base64,"},{"id":"112-1-A-48","exam":"112-1","q":48,"unit":"網路與通訊","topic":"數位科技","stem":"阿信在網路經營自媒體商業營利，使用下列哪個軟體授權最可能會有侵害著作財產權之虞？","options":["公共軟體(Public Domain Software)","CC0(Creative Commons Zero)","免費軟體(Freeware)","創用 CC(Creative Commons)"],"answer":"C","official":"免費軟體有著作權，只能自己使用、複製，但不能做\n為商業用途；自媒體商業營利屬於商業行為，所以不\n能使用免費軟體"},{"id":"112-1-A-49","exam":"112-1","q":49,"unit":"資安與資訊倫理","topic":"數位科技","stem":"有關智慧財產權的敘述，下列何者正確？","options":["影片在拍攝完後，即享有著作人格權、著作財產權","購買一套 Office 軟體，可安裝於筆記型電腦、桌面主機等數台電腦","可將合法購買的 Photoshop 軟體借給同學使用","可將創作輸出成 psd 開放格式，確保文件可以自由交換、流通"],"answer":"A","official":"(B) 購買一套 Office 軟體，只能安裝在 1 台電腦\n(C) 電腦軟體為自己使用目的而複製程式為合法，無\n須得原著作權人同意，但複製之軟體不得借與或租與\n他人，或向公眾發售，如有此行為者，則侵害著作權\n之重製權\n(D) psd 檔為 Photoshop 的封閉檔案格式，受到專利和\n版權的保護"},{"id":"112-1-A-50","exam":"112-1","q":50,"unit":"作業系統與軟體","topic":"數位科技","stem":"有關軟體授權的敘述，下列何者正確？","options":["公共軟體必需公開原始碼，提供使用者檢視、修改","採用 GPL 授權方式，使用者可以自由使用、散佈、修改軟體","免費軟體試用期過後，需付費才能繼續使用","不可以將下載的自由軟體，燒錄成光碟進行販售"],"answer":"B","official":"(A) 公共軟體不具有著作權，使用者可以任意使用，\n但是否公開原始碼不在公共軟體規範內\n(C) 共享軟體試用期過後，需付費才能繼續使用；免\n費軟體授權免費使用，沒有試用期的限制\n(D) 自由軟體採用 GPL 授權，有使用、複製、散佈、\n修改的自由，所以可以燒錄成光碟進行販售"}]);
